mapper.select:
SELECT coalesce(sum(t.Contract_Amount),0) res FROM (
select sum(coalesce(Contract_Amount,0)) Contract_Amount
from
ins_tra_funds
where
STATUS= '6'

    AND IS_ACCUMULATED != '1'

and DELFLAG_ = '1'
and DATE_FORMAT(TRAN_DATE, '%Y') = #{year}
and is_CashSubscription = '1'

    and REL_ID IN (
    SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId}) AND
    pid != #{relId}
    union ALL
    SELECT pid FROM bus_rel_org WHERE pid = #{relId})
    
        and Contract_Amount  >  500
    


    and REL_ID = #{relId}
    and REL_TYPE = #{relType}
    
        and Contract_Amount  >  500
    


    and REL_ID = #{relId}
    and REL_TYPE = #{relType}
    
        and Contract_Amount  >  50
    


    AND (Major_Type is NULL OR Major_Type = 2)


    AND Tra_sub_Name = #{traSubName}

/*GROUP BY CONTRACT_NO
HAVING COUNT(CONTRACT_NO) = 1*/
) t order by res desc limit 10

select coalesce(sum(Contract_Amount),0)
from
ins_tra_funds
where
STATUS= '6'
and DELFLAG_ = '1'
and DATE_FORMAT(TRAN_DATE, '%Y') = #{year}

    and investment_type = #{investmentType}


    and is_Overseasinvestment = #{isOverseasinvestment}


    and under_involve_rel = #{underInvolveRel}


    and REL_ID IN (
    SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId})
    AND pid != #{relId}
    union ALL
    SELECT pid FROM bus_rel_org WHERE pid = #{relId}
    union ALL
    SELECT pid FROM bus_rel_psn WHERE pid = #{relId})


    AND Tra_sub_Name = #{traSubName}

        SELECT TRAN_DATE as tranDate,REL_NAME as relName,is_HoldingSubsidiary as isHoldingSubsidiary ,
        PRODUCT_NAME as productName,TRADE_AMOUNT as tradeAmount,Contract_Amount as contractAmount,
        TRADE_SUBJECT as tradeSubject
        from ins_tra_funds
        WHERE 1=1
        
            and DATE_FORMAT(TRAN_DATE, '%Y')=#{year}
        

        
            and QUARTER(TRAN_DATE)=#{quarter}
        

        
            and Tra_sub_Name=#{subOrg}
        
        and DELFLAG_=1
        and STATUS=6

SELECT TRAN_DATE as tranDate,REL_NAME as relName,is_HoldingSubsidiary as isHoldingSubsidiary , PRODUCT_NAME as productName,TRADE_AMOUNT as tradeAmount,Contract_Amount as contractAmount, TRADE_SUBJECT as tradeSubject from ins_tra_funds WHERE 1=1 and (DATE_FORMAT(TRAN_DATE, '%Y') < #{year} or (DATE_FORMAT(TRAN_DATE, '%Y') = #{year} and QUARTER(TRAN_DATE) < #{quarter})) and (date_part('year',BUS_END_TIME) > #{year} or (date_part('year',BUS_END_TIME) = #{year} and QUARTER(BUS_END_TIME) >= #{quarter}))
and Tra_sub_Name=#{subOrg}
and DELFLAG_=1 and STATUS=6

SELECT sum(coalesce(t.Contract_Amount,0)) FROM (
select sum(coalesce(Contract_Amount,0)) Contract_Amount
from
ins_tra_funds
where
STATUS in ('1','3','4')
AND (IS_ACCUMULATED is NULL OR IS_ACCUMULATED = '0')
and DELFLAG_ = '1'
and DATE_FORMAT(TRAN_DATE, '%Y') = #{year}
and is_CashSubscription = '1'

    and REL_ID IN (
    SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId})
    AND pid != #{relId}
    union ALL
    SELECT pid FROM bus_rel_org WHERE pid = #{relId})
    and Contract_Amount  >  500
    and REL_TYPE = #{relType}


    and REL_ID = #{relId}
    and REL_TYPE = #{relType}
    and Contract_Amount  >  500


    and REL_ID = #{relId}
    and REL_TYPE = #{relType}
    and Contract_Amount  >  50


    AND Tra_sub_Name = #{traSubName}

AND (Major_Type is NULL OR Major_Type = 2)
/*GROUP BY CONTRACT_NO
HAVING COUNT(CONTRACT_NO) = 1*/
) t

mapper.update:
UPDATE ins_tra_funds
SET IS_ACCUMULATED = '1'
WHERE
STATUS = '6'
AND (IS_ACCUMULATED is NULL OR IS_ACCUMULATED = '0')
AND DELFLAG_ = '1'
AND YEAR ( TRAN_DATE ) = #{year}
AND is_CashSubscription = '1'

    and REL_ID IN (
    SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId})
    AND pid != #{relId}
    union ALL
    SELECT pid FROM bus_rel_org WHERE pid = #{relId})
    and Contract_Amount  >  500


    AND REL_ID = #{relId}
    AND REL_TYPE = #{relType}
    AND Contract_Amount> 500


    AND REL_ID = #{relId}
    AND REL_TYPE = #{relType}
    AND Contract_Amount> 50


    AND Tra_sub_Name = #{traSubName}

AND (Major_Type is NULL OR Major_Type = 2)

update ins_tra_funds
set TRAN_DATE = #{contractDate},TRADE_AMOUNT = #{relTrandeAmount},STATUS = '6'
Where pid = #{pid}

mapper.select:
SELECT iti.REL_ID as relId, iti.REL_NAME as relName, iti.TRAN_TYPE as tranType, iti.REMARK as remark, iti.TRAN_DATE as tranDate, iti.TRA_SUB_NAME as traSubName, iti.manager_org as managerOrg, SUM(iti.prac_trade_amount) over(partition by rel_id,tran_type,investment_type
,manager_org
) as contractAmount, iti.investment_type AS tranOverView FROM INS_TRA_FUNDS iti WHERE iti.STATUS IN ('6','7','10') AND iti.DELFLAG_ = '1' and iti.tran_type is not null and iti.prac_trade_amount is not null and iti.investment_type is not null
and to_char(iti.TRAN_DATE,'YYYY-MM-DD') BETWEEN #{staTime} AND #{endTime}

from ins_tra_funds where 1=1 and data_version = 'E2.0' and PRAC_TRADE_AMOUNT IS null and STATUS != '9'
AND CONTRACT_NO = #{contractNo}
AND REL_NUMBER = #{relNumber}
AND DELFLAG_ = '1'

        SELECT *
        FROM ins_tra_funds
        WHERE
        1=1
             AND data_version = 'E2.0'
        
            and  contract_no like
            CONCAT(CONCAT('%', #{contractNo}), '%')
        
        
            and REL_NUMBER = #{relNumber}
        
        
            and rel_Name like
            CONCAT(CONCAT('%', #{relName}), '%')
        
        
            and bus_type = #{busType}
        
        
            and DATE_FORMAT(tran_Date,'%Y-%m-%d') >= #{startTranDate}
        
        
            and DATE_FORMAT(tran_Date,'%Y-%m-%d') <= #{endTranDate}
        
        
            and consider_Type = #{considerType}
        
        
            and major_Trade=#{majorTrade}
        
        
            and status = #{status}
        
        
            and  (AMEND_ID IN (SELECT staff_code_ FROM sys_staff WHERE  dept_code_ = #{deptCode}) or AMEND_ID IS NULL)
        
        
            and subStr(created_time_,1,10) = #{createTimeString}
        
        
            and data_sources = #{dataSources}
        
        
            

            
            
                OR AMEND_NAME = 'System'
                OR AMEND_NAME IS NULL
            
        
        and ((DELFLAG_ = '1'))
        ORDER BY MODIFIED_TIME_ DESC,CREATED_TIME_ DESC

SELECT * FROM ins_tra_funds WHERE 1=1
and TRANS_NUM = #{transNum}
and ((DELFLAG_ = '1')) ORDER BY MODIFIED_TIME_ DESC

select CONTRACT_NO, TRAN_TYPE from ( SELECT CONTRACT_NO, TRAN_TYPE FROM ins_tra_funds WHERE data_version = 'E2.0'
AND CONTRACT_NO = #{contractNo}
union all SELECT CONTRACT_NO, TRAN_TYPE FROM ins_tra_service WHERE data_version = 'E2.0'
AND CONTRACT_NO = #{contractNo}
union all SELECT CONTRACT_NO, TRAN_TYPE FROM ins_tra_business WHERE data_version = 'E2.0'
AND CONTRACT_NO = #{contractNo}
union all SELECT CONTRACT_NO, TRAN_TYPE FROM ins_tra_interest WHERE data_version = 'E2.0'
AND CONTRACT_NO = #{contractNo}
) a
